-- actualizar que se modifico la tupla actual por el proyecto de id 'idproyecto'
UPDATE mod_estructuracomp.dat_cargo set modificado[NEW.idproyecto] = 1 WHERE idestado = 0 AND idcargo = NEW.idcargo;

RETURN NEW;
