$BODY$;

ALTER FUNCTION mod_estructuracomp.ft_trabajocargo()
    OWNER TO zeolides;

GRANT EXECUTE ON FUNCTION mod_estructuracomp.ft_trabajocargo() TO zeolides;

REVOKE ALL ON FUNCTION mod_estructuracomp.ft_trabajocargo() FROM PUBLIC;

CREATE TRIGGER t_insertar_dat_cargo
    BEFORE INSERT
    ON mod_estructuracomp.dat_cargo
    FOR EACH ROW
    EXECUTE FUNCTION mod_estructuracomp.ft_trabajocargo();

DROP TRIGGER IF EXISTS tr_actualizar_activo ON mod_nomina.conf_plantillanominalcargo;
DROP FUNCTION IF EXISTS mod_nomina.ft_actualizar_activo_cargo_plantillanominal();

DROP TRIGGER IF EXISTS tr_actualizar_activo_cargo_plantillanominal ON mod_estructuracomp.nom_filaestruc;
DROP FUNCTION IF EXISTS mod_estructuracomp.ft_actualizar_activo_cargo_plantillanominal();

CREATE OR REPLACE FUNCTION mod_estructuracomp.ft_actualizar_activo_cargo_plantillanominal()
RETURNS TRIGGER AS $$
BEGIN
    -- Salida temprana: si no es concepto relevante, no hacer nada
    IF NEW.idconcepto NOT IN (7, 10) THEN
        RETURN NEW;
    END IF;
    
    -- Si se está actualizando y fechafin cambia a NOT NULL con conceptos 7 o 10
    IF (TG_OP = 'UPDATE') THEN
        -- Verificar si fechafin cambió de NULL a NOT NULL
        IF (OLD.fechafin IS NULL AND NEW.fechafin IS NOT NULL) THEN
            UPDATE mod_nomina.conf_plantillanominalcargo
            SET activo = false
            WHERE idcargo = NEW.idfila AND activo = true;
        
        -- Si se está quitando la fecha de fin (de NOT NULL a NULL)
        ELSIF (OLD.fechafin IS NOT NULL AND NEW.fechafin IS NULL) THEN
            UPDATE mod_nomina.conf_plantillanominalcargo
            SET activo = true
            WHERE idcargo = NEW.idfila AND activo = false;
        END IF;
    
   END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER tr_actualizar_activo_cargo_plantillanominal
    AFTER UPDATE OF fechafin
    ON mod_estructuracomp.nom_filaestruc
    FOR EACH ROW
    EXECUTE FUNCTION mod_estructuracomp.ft_actualizar_activo_cargo_plantillanominal();

CREATE TABLE IF NOT EXISTS nom_filaestruc_audit (
    id_audit SERIAL PRIMARY KEY,
    operacion CHAR(1) NOT NULL,
    tabla_afectada TEXT NOT NULL,
    datos_viejos TEXT,             
    datos_nuevos TEXT,
    usuario TEXT NOT NULL,
    momento TIMESTAMP NOT NULL
);

CREATE OR REPLACE FUNCTION mod_estructuracomp.ft_actualizar_ordenunico_plantillanominal()
    RETURNS trigger
    LANGUAGE 'plpgsql'
    COST 100
    VOLATILE NOT LEAKPROOF
AS $BODY$
DECLARE
BEGIN

IF (TG_OP = 'UPDATE' AND NEW.ordenunico IS DISTINCT FROM OLD.ordenunico ) THEN

	UPDATE mod_nomina.conf_plantillanominalcargo
	SET ordenunico = NEW.ordenunico
	WHERE idcargo = NEW.idfila;

	RETURN NEW;

ELSEIF (TG_OP = 'DELETE') THEN

	UPDATE mod_nomina.conf_plantillanominalcargo
	SET activo = false
	WHERE idcargo = OLD.idfila;

	INSERT INTO nom_filaestruc_audit (operacion, tabla_afectada, datos_viejos, usuario, momento)
        VALUES ('D', TG_TABLE_NAME, row_to_json(OLD.*), current_user, now());

    RETURN OLD;

END IF;

 RETURN NEW;

END;
$BODY$;

ALTER FUNCTION mod_estructuracomp.ft_actualizar_ordenunico_plantillanominal() OWNER TO zeolides;

DROP TRIGGER IF EXISTS tr_actualizar_plantillanominalcargo ON mod_estructuracomp.nom_filaestruc;
CREATE TRIGGER tr_actualizar_plantillanominalcargo
    AFTER UPDATE OF ordenunico OR DELETE
    ON mod_estructuracomp.nom_filaestruc
    FOR EACH ROW
    EXECUTE FUNCTION mod_estructuracomp.ft_actualizar_ordenunico_plantillanominal();